// Reuse the core's error translations; do not maintain a second incomplete
// list for errors generated by Anchor. The desktop currently displays Chinese.
import chinese from '../../../../../internal/apierror/locales/zh-CN.json';
import english from '../../../../../internal/apierror/locales/en.json';

const aliases: Record<string, string> = { invalid_response: 'upstream_unsupported_content', unsupported_upstream_response: 'upstream_unsupported_content', upstream_stream_error: 'upstream_stream_incomplete', internal_error: 'internal' };
const logErrors: Record<string, string> = {
  invalid_upstream_response: '上游响应格式无效，请查看结构诊断中的具体原因。',
  upstream_connect: '连接上游失败，请检查网络、域名和供应商地址。',
  upstream_unavailable: '上游返回不可用状态，请查看尝试中的 HTTP 状态。',
  rate_limited: '上游限流，请查看 Key 配额和冷却状态。', authentication: '上游拒绝了身份验证，请检查供应商 Key。',
  encrypted_context_rejected: '上游拒绝了历史加密上下文。', stream_interrupted: '上游响应流在完整结束前中断。',
  request_interrupted: '请求被中断，结果未确认。', core_interrupted: '核心退出导致请求中断，最终结果未知。',
  client_cancelled: '客户端取消了请求。', client_write_failed: '向客户端写入响应失败。', no_available_key: '没有可用的 Key。',
};

export function errorExplanation(code: string, language: 'zh-CN' | 'en' = 'zh-CN'): string {
  const messages: Record<string, string> = language === 'en' ? english : chinese;
  const id = Object.hasOwn(aliases, code) ? aliases[code] : code;
  const text = Object.hasOwn(messages, id) ? messages[id] : undefined;
  // Parameterized API messages need arguments unavailable in old logs.
  if (text && !/%[ds]/.test(text)) return text;
  if (language === 'zh-CN' && Object.hasOwn(logErrors, code)) return logErrors[code];
  return language === 'en' ? 'No detailed explanation was recorded for this error.' : code ? '此错误未记录更具体的原因，现有日志无法还原原始报错。' : '日志未记录具体错误码。';
}

const causes: Record<string, string> = { timeout: '等待超时', cancelled: '请求已取消', dns: '域名解析失败', tls_certificate: 'TLS 证书校验失败', connection_reset: '连接被对端重置', connection_refused: '连接被拒绝', broken_pipe: '发送时连接已断开', unexpected_eof: '对端提前关闭连接', transport: '未分类的网络传输错误' };
export function errorDiagnosis(code: string, evidence: Record<string, unknown>): string {
  const identity = typeof evidence.anchor_error_id === 'string' && Object.hasOwn(chinese, evidence.anchor_error_id) ? evidence.anchor_error_id : code;
  const remote: Record<string, string> = { invalid_api_key: '上游报告 Key 无效。', insufficient_quota: '上游报告余额或配额不足。', rate_limit: '上游报告请求限流。', model_not_found: '上游报告模型不存在或不可访问。', permission_denied: '上游报告权限不足。', context_length: '上游报告上下文超限。', invalid_request: '上游报告请求参数无效。', overloaded: '上游报告服务过载。', server_error: '上游报告服务内部错误。' };
  const category = evidence.upstream_error_category;
  const upstream = typeof category === 'string' && Object.hasOwn(remote, category) ? ` ${remote[category]}` : '';
  const cause = evidence.transport_cause;
  if (typeof cause !== 'string' || !Object.hasOwn(causes, cause)) return errorExplanation(identity) + upstream;
  const phase = evidence.transport_phase === 'response_headers' ? '等待上游 HTTP 响应头' : '连接上游';
  const seconds = Number(evidence.provider_timeout_seconds);
  const budget = Number.isSafeInteger(seconds) && seconds > 0 ? `供应商请求超时配置为 ${seconds} 秒。` : '';
  return `${errorExplanation(identity)}${upstream} ${phase}阶段：${causes[cause]}。${budget}`;
}
